<script setup>
import { computed } from 'vue'
import router from '../../router';
import { config } from '../../constants';

// VARS
const BACKEND_URL = config.url.BACKEND_URL;

// PROPS
const props = defineProps({
    dr: {
        type: Object,
        required: true,
    },
});

var { source, sourceLogo, id, drUri, articleuuid } = props.dr;

if (source === 'sumnews.net') {
    sourceLogo = `data:image/png;base64,`
}

const wasVisited = computed(() => {
    const dailyRecapInLocalStorage = JSON.parse(localStorage.getItem('dailyRecaps'));
    // Get the current 'dailyrecapbutton' that was clicked on
    var dailyRecapButton = dailyRecapInLocalStorage.dailyRecapButtons.filter(button => button.drUri == drUri)[0];
    // Update the object value
    return dailyRecapButton.wasVisited;
})

// Redirect the user to the correct URI after finding out the first article uuid
async function renderDailyRecap(id, drUri, articleuuid) {
    // Place current button at the end of DailyRecapButtons array
    const dailyRecapInLocalStorage = JSON.parse(localStorage.getItem('dailyRecaps'));
    // Get the current 'dailyrecapbutton' that was clicked on
    var dailyRecapButtonsArray = dailyRecapInLocalStorage.dailyRecapButtons;
    var dailyRecapButton = dailyRecapInLocalStorage.dailyRecapButtons.filter(button => button.drUri == drUri)[0];
    // Update the object value
    dailyRecapButton.wasVisited = true;

    // Place the current button at the end of the array
    const index = dailyRecapButtonsArray.indexOf(dailyRecapButton);
    dailyRecapButtonsArray.splice(index, 1);
    dailyRecapButtonsArray.push(dailyRecapButton);

    // Save the updated array into local storage
    // const now = new Date();
    localStorage.setItem('dailyRecaps', JSON.stringify({ "dailyRecapButtons": dailyRecapButtonsArray }));

    router.push({
        name: 'dailyrecap', params: {
            dailyrecapUUID: id,
            drUri: drUri,
            articleUUID: articleuuid,
        }
    })
}
</script>

<template>
    <button class="mycontainer" @click="renderDailyRecap(props.dr.id, props.dr.drUri, props.dr.articleuuid)">
        <div class="dailyrecap">
            <div class="logo-container">
                <img class="logo" :alt="source" :src="'data:image/jpeg;base64,' + sourceLogo"
                    v-if="source != 'sumnews.net'">
                <img class="logo" :alt="source" :src="sourceLogo" v-else>
                <div class="shader" :class="{ visited: wasVisited }"></div>
            </div>
        </div>
        <!-- <p class="source-title">{{ source }}</p> -->
    </button>
</template>

<style scoped>
.mycontainer {
    border-radius: var(--border-radius);
    text-align: center;
    width: 60px;
    flex: 0 0 auto;
}

.dailyrecap {
    height: fit-content;
    width: fit-content;
}

.logo-container {
    position: relative;
    width: 60px;
    height: 60px;
}

.logo {
    height: 60px;
    width: 60px;
    border-radius: 10px;
    border: 2px solid black;
    position: relative;
    z-index: 1;
}

.shader {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    border-radius: 10px;
    pointer-events: none;
    z-index: 2;
}

.visited {
    background: rgba(0, 0, 0, 0.4);
}

.source-title {
    font-size: 11px;
    display: -webkit-box;
    -webkit-line-clamp: 1;
    -webkit-box-orient: vertical;
    overflow: hidden;
    color: black;
}
</style>